# Generated by Duke Forger.
# Imports the creator's Meshy assets into /Game/Duke, builds the city materials, and writes
# Content/Duke/Data/assets.json so the game code can find everything.
# Run headless:  UnrealEditor-Cmd.exe DukeGame.uproject -run=pythonscript -script="<abs path to this file>" -unattended -nosplash
import json, os, re, traceback
import unreal

PROJECT = unreal.Paths.convert_relative_path_to_full(unreal.Paths.project_dir())
IMPORT = os.path.join(PROJECT, 'Import')
DATA = os.path.join(PROJECT, 'Content', 'Duke', 'Data')
SAVED = os.path.join(PROJECT, 'Saved')
LOG = []
RESULT = {'characters': {}, 'vehicles': {}, 'weapons': {}, 'landmarks': {}, 'kit': {}, 'materials': {}, 'errors': []}

def log(msg):
    unreal.log('[Duke] ' + msg)
    LOG.append(msg)

def err(msg):
    unreal.log_warning('[Duke] ' + msg)
    RESULT['errors'].append(msg)
    LOG.append('ERROR: ' + msg)

EAL = unreal.EditorAssetLibrary
TOOLS = unreal.AssetToolsHelpers.get_asset_tools()
MEL = unreal.MaterialEditingLibrary

# Use the classic FBX importer so FbxImportUI options (skeleton, animation-only) are honoured.
try:
    unreal.SystemLibrary.execute_console_command(None, 'Interchange.FeatureFlags.Import.FBX 0')
except Exception:
    pass

def run_import(filename, dest, options=None):
    t = unreal.AssetImportTask()
    t.set_editor_property('filename', filename)
    t.set_editor_property('destination_path', dest)
    t.set_editor_property('automated', True)
    t.set_editor_property('replace_existing', True)
    t.set_editor_property('save', True)
    if options is not None:
        t.set_editor_property('options', options)
    TOOLS.import_asset_tasks([t])
    return list(t.get_editor_property('imported_object_paths') or [])

def assets_of(folder, cls):
    out = []
    for p in EAL.list_assets(folder, recursive=True, include_folder=False):
        try:
            a = EAL.load_asset(p)
            if isinstance(a, cls):
                out.append(a.get_path_name())
        except Exception:
            pass
    return out

def fbx_options(kind, skeleton=None):
    o = unreal.FbxImportUI()
    o.set_editor_property('automated_import_should_detect_type', False)
    if kind == 'static':
        o.set_editor_property('import_mesh', True)
        o.set_editor_property('import_as_skeletal', False)
        o.set_editor_property('mesh_type_to_import', unreal.FBXImportType.FBXIT_STATIC_MESH)
        o.set_editor_property('import_materials', True)
        o.set_editor_property('import_textures', True)
        o.static_mesh_import_data.set_editor_property('combine_meshes', True)
        o.static_mesh_import_data.set_editor_property('generate_lightmap_u_vs', False)
    elif kind == 'skeletal':
        o.set_editor_property('import_mesh', True)
        o.set_editor_property('import_as_skeletal', True)
        o.set_editor_property('mesh_type_to_import', unreal.FBXImportType.FBXIT_SKELETAL_MESH)
        o.set_editor_property('import_animations', False)
        o.set_editor_property('import_materials', True)
        o.set_editor_property('import_textures', True)
        o.set_editor_property('create_physics_asset', True)
    else:  # animation only
        o.set_editor_property('import_mesh', False)
        o.set_editor_property('import_as_skeletal', True)
        o.set_editor_property('mesh_type_to_import', unreal.FBXImportType.FBXIT_ANIMATION)
        o.set_editor_property('import_animations', True)
        o.set_editor_property('import_materials', False)
        o.set_editor_property('import_textures', False)
        if skeleton is not None:
            o.set_editor_property('skeleton', skeleton)
    return o

def import_static(entry, dest):
    """GLB through Interchange first (keeps textures), FBX as a fallback."""
    paths = []
    glb = entry.get('glb')
    fbx = entry.get('fbx')
    if glb and os.path.exists(os.path.join(PROJECT, glb)):
        run_import(os.path.join(PROJECT, glb), dest)
        paths = assets_of(dest, unreal.StaticMesh)
    if not paths and fbx and os.path.exists(os.path.join(PROJECT, fbx)):
        run_import(os.path.join(PROJECT, fbx), dest, fbx_options('static'))
        paths = assets_of(dest, unreal.StaticMesh)
    if not paths:
        return None
    # if a GLB produced several meshes, pick the biggest
    best, best_size = None, -1
    for p in paths:
        m = EAL.load_asset(p)
        b = m.get_bounds()
        size = b.box_extent.x * b.box_extent.y * b.box_extent.z
        if size > best_size:
            best, best_size = p, size
    return best

def safe(i):
    return 'A' + re.sub(r'[^A-Za-z0-9]', '_', i)

def import_character(cid, entry):
    dest = '/Game/Duke/Characters/' + safe(cid)
    rig = entry.get('rig')
    if not rig or not os.path.exists(os.path.join(PROJECT, rig)):
        err('Character %s has no rig FBX' % cid)
        return
    run_import(os.path.join(PROJECT, rig), dest, fbx_options('skeletal'))
    meshes = assets_of(dest, unreal.SkeletalMesh)
    skels = assets_of(dest, unreal.Skeleton)
    if not meshes:
        err('Character %s: skeletal mesh import failed' % cid)
        return
    out = {'mesh': meshes[0], 'anims': {}}
    skeleton = EAL.load_asset(skels[0]) if skels else None
    for name, rel in (entry.get('anims') or {}).items():
        f = os.path.join(PROJECT, rel)
        if not os.path.exists(f):
            continue
        adest = dest + '/Anims/' + name
        run_import(f, adest, fbx_options('anim', skeleton))
        seqs = assets_of(adest, unreal.AnimSequence)
        if seqs:
            out['anims'][name] = seqs[0]
        else:
            err('Character %s: animation %s did not import' % (cid, name))
    RESULT['characters'][cid] = out
    log('Character %s: mesh + %d animations' % (cid, len(out['anims'])))

# ---------- materials ----------
FACADE_HLSL = r'''
float3 p = WP / 100.0;
float3 n = normalize(N);
if (abs(n.z) > 0.5) { return Mode < 0.5 ? Col * 0.35 : (Mode < 1.5 ? float3(0,0,0) : float3(0.85,0,0)); }
float u = abs(n.x) > 0.5 ? p.y : p.x;
float v = p.z;
float fh = 3.6; float cw = 3.0;
float2 f = frac(float2(u / cw, v / fh));
float2 id = floor(float2(u / cw, v / fh));
float win = step(0.2, f.x) * step(f.x, 0.8) * step(0.26, f.y) * step(f.y, 0.84);
if (v < 4.2) win = step(0.42, v) * step(v, 3.1) * step(0.08, frac(u / 5.5)) * step(frac(u / 5.5), 0.92);
float h = frac(sin(dot(id + floor(p.xy * 0.02), float2(12.9898, 78.233))) * 43758.5453);
float lit = step(h, 0.1 + 0.35 * Night) * win;
float3 warm = lerp(float3(1.0, 0.72, 0.42), float3(0.72, 0.86, 1.0), step(0.75, frac(h * 7.31)));
if (Mode < 0.5) return lerp(Col * (0.85 + 0.15 * frac(h * 3.1)), float3(0.03, 0.035, 0.04), win);
if (Mode < 1.5) return warm * lit * (0.3 + 8.0 * Night);
return float3(lerp(Rough, 0.06, win), 0, 0);
'''

def new_material(name):
    path = '/Game/Duke/Materials'
    full = path + '/' + name
    if EAL.does_asset_exist(full):
        EAL.delete_asset(full)
    return TOOLS.create_asset(name, path, unreal.Material, unreal.MaterialFactoryNew()), full

def param_vec(m, name, default, x, y):
    e = MEL.create_material_expression(m, unreal.MaterialExpressionVectorParameter, x, y)
    e.set_editor_property('parameter_name', name)
    e.set_editor_property('default_value', unreal.LinearColor(*default))
    return e

def param_scalar(m, name, default, x, y):
    e = MEL.create_material_expression(m, unreal.MaterialExpressionScalarParameter, x, y)
    e.set_editor_property('parameter_name', name)
    e.set_editor_property('default_value', default)
    return e

def build_color_material():
    m, full = new_material('M_DukeColor')
    col = param_vec(m, 'Color', (0.6, 0.6, 0.6, 1.0), -700, -100)
    rough = param_scalar(m, 'Roughness', 0.6, -700, 100)
    metal = param_scalar(m, 'Metallic', 0.0, -700, 200)
    emis = param_scalar(m, 'Emissive', 0.0, -700, 300)
    night = param_scalar(m, 'Night', 0.0, -700, 400)
    glow = MEL.create_material_expression(m, unreal.MaterialExpressionMultiply, -450, 300)
    MEL.connect_material_expressions(emis, '', glow, 'A')
    MEL.connect_material_expressions(night, '', glow, 'B')
    glowc = MEL.create_material_expression(m, unreal.MaterialExpressionMultiply, -250, 300)
    MEL.connect_material_expressions(col, '', glowc, 'A')
    MEL.connect_material_expressions(glow, '', glowc, 'B')
    MEL.connect_material_property(col, '', unreal.MaterialProperty.MP_BASE_COLOR)
    MEL.connect_material_property(rough, '', unreal.MaterialProperty.MP_ROUGHNESS)
    MEL.connect_material_property(metal, '', unreal.MaterialProperty.MP_METALLIC)
    MEL.connect_material_property(glowc, '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    MEL.recompile_material(m)
    EAL.save_asset(full)
    return m.get_path_name()

def build_facade_material():
    m, full = new_material('M_DukeFacade')
    col = param_vec(m, 'Color', (0.6, 0.6, 0.6, 1.0), -900, -100)
    rough = param_scalar(m, 'Roughness', 0.7, -900, 50)
    metal = param_scalar(m, 'Metallic', 0.0, -900, 150)
    night = param_scalar(m, 'Night', 0.0, -900, 250)
    wp = MEL.create_material_expression(m, unreal.MaterialExpressionWorldPosition, -900, 350)
    nrm = MEL.create_material_expression(m, unreal.MaterialExpressionVertexNormalWS, -900, 450)
    outs = []
    for mode, y in ((0, -150), (1, 100), (2, 350)):
        c = MEL.create_material_expression(m, unreal.MaterialExpressionCustom, -500, y)
        c.set_editor_property('code', FACADE_HLSL.replace('Mode', str(float(mode))))
        c.set_editor_property('output_type', unreal.CustomMaterialOutputType.CMOT_FLOAT3)
        inputs = []
        for nm in ('WP', 'N', 'Col', 'Night', 'Rough'):
            ci = unreal.CustomInput()
            ci.set_editor_property('input_name', nm)
            inputs.append(ci)
        c.set_editor_property('inputs', inputs)
        MEL.connect_material_expressions(wp, '', c, 'WP')
        MEL.connect_material_expressions(nrm, '', c, 'N')
        MEL.connect_material_expressions(col, '', c, 'Col')
        MEL.connect_material_expressions(night, '', c, 'Night')
        MEL.connect_material_expressions(rough, '', c, 'Rough')
        outs.append(c)
    mask = MEL.create_material_expression(m, unreal.MaterialExpressionComponentMask, -250, 350)
    mask.set_editor_property('r', True)
    mask.set_editor_property('g', False)
    mask.set_editor_property('b', False)
    mask.set_editor_property('a', False)
    MEL.connect_material_expressions(outs[2], '', mask, '')
    MEL.connect_material_property(outs[0], '', unreal.MaterialProperty.MP_BASE_COLOR)
    MEL.connect_material_property(outs[1], '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    MEL.connect_material_property(mask, '', unreal.MaterialProperty.MP_ROUGHNESS)
    MEL.connect_material_property(metal, '', unreal.MaterialProperty.MP_METALLIC)
    MEL.recompile_material(m)
    EAL.save_asset(full)
    return m.get_path_name()

def main():
    os.makedirs(DATA, exist_ok=True)
    manifest_path = os.path.join(IMPORT, 'manifest.json')
    manifest = json.load(open(manifest_path, encoding='utf-8')) if os.path.exists(manifest_path) else {}
    for step, fn in (('color material', build_color_material), ('facade material', build_facade_material)):
        try:
            key = 'color' if step.startswith('color') else 'facade'
            RESULT['materials'][key] = fn()
            log('Created ' + step)
        except Exception as e:
            err('Could not create %s (%s) - using engine material' % (step, e))
    if 'color' in RESULT['materials']:
        RESULT['materials']['water'] = RESULT['materials']['color']
    for cid, entry in (manifest.get('characters') or {}).items():
        try:
            import_character(cid, entry)
        except Exception:
            err('Character %s failed: %s' % (cid, traceback.format_exc(limit=2)))
    for group, folder in (('vehicles', 'Vehicles'), ('weapons', 'Weapons'), ('landmarks', 'Landmarks')):
        for eid, entry in (manifest.get(group) or {}).items():
            try:
                path = import_static(entry, '/Game/Duke/%s/%s' % (folder, safe(eid)))
                if path:
                    RESULT[group][eid] = {'mesh': path}
                    log('%s %s imported' % (group[:-1].capitalize(), eid))
                else:
                    err('%s %s: no mesh imported' % (group[:-1].capitalize(), eid))
            except Exception:
                err('%s %s failed: %s' % (group, eid, traceback.format_exc(limit=2)))
    for name, entry in (manifest.get('kit') or {}).items():
        try:
            path = import_static(entry, '/Game/Duke/Kit/' + name)
            if path:
                RESULT['kit'][name] = path
        except Exception:
            err('Kit %s failed' % name)
    EAL.save_directory('/Game/Duke', only_if_is_dirty=False, recursive=True)
    with open(os.path.join(DATA, 'assets.json'), 'w', encoding='utf-8') as f:
        json.dump(RESULT, f, indent=2)
    log('Wrote assets.json')

try:
    main()
    status = 'ok'
except Exception:
    err(traceback.format_exc())
    status = 'failed'
os.makedirs(SAVED, exist_ok=True)
with open(os.path.join(SAVED, 'DukeImport.json'), 'w', encoding='utf-8') as f:
    json.dump({'status': status, 'log': LOG, 'errors': RESULT['errors']}, f, indent=2)
